C='Confirmed unauthorized credential write';E='Confirmed privilege escalation';P='Potential vulnerability requiring further verification';A='Adequately protected';U='Unresolved due to missing trusted data'
rows=[]
def add(i,rf,cf,fn,write,scope,proof,classes,impact,rank='P0',project='main'):
 root={'main':main,'ai':ai}[project];s=(root/cf).read_text();start=re.search(r'exports\.'+fn+r'\s*=',s)
 assert start,(cf,fn)
 end=re.search(r'\nexports\.',s[start.end():]);endpos=start.end()+end.start() if end else len(s)
 text=s[start.start():endpos];line=s[:start.start()].count('\n')+1
 bindings=[]
 rs=(root/rf).read_text()
 for m in re.finditer(r'router\.(get|post|put|delete|patch)\(\s*"([^"]+)"\s*,([\s\S]*?)\);',rs):
  if re.search(r'\b'+fn+r'\b',m[3]):bindings.append({'method':m[1].upper(),'path':m[2],'line':rs[:m.start()].count('\n')+1,'middleware_and_handler':re.sub(r'\s+',' ',m[3]).strip().strip(',')})
 # The retained recovery functions are deliberately not registered anymore.
 if fn in ['resetPassword','forgotPassword']:
  p='/gratis/reset-password/:userid' if fn=='resetPassword' else '/gratis/forgot-password'
  bindings=[{'method':'PUT','path':p,'binding':'terminal inline 503; original function unbound'}]
 assert bindings,(cf,fn)
 active=fn not in ['resetPassword','forgotPassword']
 chains=' '.join(str(b) for b in bindings)
 legacy='authCheck' in chains
 row={'id':i,'project':project,'route_file':rf,'routes':bindings,'controller':cf,'function':fn,'controller_line':line,'write':write,'query_scope':scope,'independent_proof_or_permission':proof,'classification':classes,'priority':rank,'impact':impact,'authentication':{'signature_verified':False,'expiration_verified':False,'identity':'decoded unverified email' if legacy else ('not reached: terminal denial' if not active else 'none'),'current_role_membership':'email + caller-selected primary store; permits admin/moderator/cashier' if 'adminGratisCheck' in chains else 'no independent current privileged grant','explicit_target_permission':proof},'source_sha256':hashlib.sha256((root/cf).read_bytes()).hexdigest(),'mutation_or_issuance_lines':[line+text[:m.start()].count('\n') for m in re.finditer(r'(?:User|Estore|Billing|Payment)\.(?:findOneAndUpdate|findByIdAndUpdate|updateOne|updateMany|findOneAndDelete|deleteMany)|new (?:User|Estore|Billing|Payment)|jwt\.sign',text)]}
 rows.append(row)
